  poly('w',[[30,53],[34,52],[35,56],[30,57]]);
  poly('r',[[31,56],[35,55],[38,57],[41,57],[42,59],[38,60],[30,58]]);rect('w',35,57,3,1);rect('ws',32,59,9,1);
  // Near leg with a strong gap and planted sneaker.
  poly('o',[[17,40],[26,40],[27,46],[23,50],[22,55],[24,58],[22,61],[11,61],[9,59],[11,55],[16,53],[16,48],[14,45]]);
  poly('p',[[18,42],[25,42],[25,46],[21,49],[17,48],[16,45]]);rect('pl',18,43,3,3);
  poly('s',[[18,48],[22,49],[20,55],[16,55],[17,52]]);rect('ss',17,52,2,3);
  poly('w',[[16,54],[21,54],[21,57],[14,58],[13,56]]);
  poly('rd',[[13,56],[17,57],[21,56],[22,59],[20,60],[11,60],[11,58]]);rect('r',12,57,4,2);rect('w',17,57,3,1);rect('ws',11,60,10,1);
  // Jacket, torso and angled vest.
