  poly('w',[[19,29],[25,28],[31,29],[34,33],[32,40],[31,42],[22,43],[17,40],[16,35]]);
  poly('ws',[[18,34],[21,36],[22,41],[30,41],[30,43],[21,43],[17,40]]);
  poly('r',[[24,29],[29,28],[32,30],[31,35],[33,39],[30,42],[25,42],[24,37]]);
  poly('rh',[[25,30],[28,29],[30,30],[29,33],[25,34]]);poly('rd',[[25,35],[30,34],[31,39],[29,41],[25,41]]);
  rect('o',24,29,1,11);rect('w',26,30,1,2);rect('o',20,42,12,2);rect('ws',24,42,3,1);
  // Far arm bends up to the backpack strap.
  poly('o',[[17,29],[20,30],[20,35],[17,38],[13,37],[12,33],[14,30]]);
