  poly('w',[[33,30],[35,30],[37,33],[36,35],[33,34]]);rect('ws',34,34,3,2);
  poly('s',[[36,35],[38,36],[41,35],[43,33],[45,33],[46,35],[44,37],[40,38],[37,37]]);
  poly('sh',[[38,35],[41,34],[43,32],[44,33],[43,35],[40,36],[38,36]]);rect('ss',38,37,4,1);rect('o',44,34,2,1);
  // Neck and shirt collar.
