  poly('o',[[23,18],[26,18],[27,21],[25,23],[22,21]]);rect('s',23,19,2,2);rect('ss',24,20,1,1);
  poly('h',[[21,13],[26,12],[30,13],[28,17],[26,15],[24,19],[22,18]]);rect('hl',24,13,3,1);rect('h',25,22,2,2);
  // Eye, far eye, cheek and mouth. Keep tiny face readable.
  rect('o',31,18,3,1);rect('o',32,19,2,3);rect('w',32,19,1,1);rect('o',37,19,1,2);rect('ss',36,22,1,1);rect('o',33,24,3,1);rect('rh',29,22,2,1);
  // Cap wraps around the hair with a long perspective brim.
  poly('o',[[15,8],[18,5],[24,3],[31,4],[35,6],[37,10],[37,13],[43,14],[44,16],[41,18],[34,17],[29,16],[21,17],[16,16],[13,14],[14,11]]);
  poly('r',[[16,9],[19,6],[24,4],[30,5],[34,7],[35,11],[34,14],[27,14],[21,16],[16,14],[15,12]]);
